testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { normalizarCadastro, camelizar } from './solution.mjs';

test('normalizarCadastro limpa os espaços e calcula o total', () => {
  assert.deepEqual(normalizarCadastro({ 'nome do cliente': '  Ana  ', qtd: '3', preco: 10 }), {
    cliente: 'Ana',
    quantidade: 3,
    total: 30
  });
  assert.deepEqual(normalizarCadastro({ 'nome do cliente': 'Bia', qtd: 2, preco: 5.5 }), {
    cliente: 'Bia',
    quantidade: 2,
    total: 11
  });
});

test('normalizarCadastro lança com campo faltando ou inválido', () => {
  assert.throws(() => normalizarCadastro({ 'nome do cliente': '  ', qtd: '3', preco: 10 }));
  assert.throws(() => normalizarCadastro({ 'nome do cliente': 'Ana', qtd: 'x', preco: 10 }));
  assert.throws(() => normalizarCadastro({ 'nome do cliente': 'Ana', qtd: '3' }));
  assert.throws(() => normalizarCadastro({ 'nome do cliente': 'Ana', qtd: '3', preco: -1 }));
});

test('camelizar transforma chaves com espaços em camelCase', () => {
  assert.equal(camelizar('nome do cliente'), 'nomeDoCliente');
  assert.equal(camelizar('PRECO unitario'), 'precoUnitario');
});

test('camelizar devolve string vazia para entrada inválida', () => {
  assert.equal(camelizar(42), '');
  assert.equal(camelizar(null), '');
});

solutionCode:
export function normalizarCadastro(entrada) {
  if (typeof entrada !== 'object' || entrada === null) {
    throw new Error('cadastro inválido');
  }
  const nomeBruto = entrada['nome do cliente'];
  const quantidadeBruta = entrada.qtd;
  const preco = entrada.preco;

  if (typeof nomeBruto !== 'string' || nomeBruto.trim() === '') {
    throw new Error('nome do cliente é obrigatório');
  }
  const quantidade = Number(quantidadeBruta);
  if (
    !Number.isInteger(quantidade) || quantidade <= 0 ||
    typeof preco !== 'number' || preco < 0
  ) {
    throw new Error('qtd e preco são obrigatórios');
  }
  return {
    cliente: nomeBruto.trim(),
    quantidade,
    total: Math.round(quantidade * preco * 100) / 100,
  };
}

export function camelizar(chave) {
  if (typeof chave !== 'string') return '';
  return chave
    .trim()
    .split(/\s+/)
    .map((palavra) => palavra.toLowerCase())
    .map((palavra, i) => (i === 0 ? palavra : palavra[0].toUpperCase() + palavra.slice(1)))
    .join('');
}
